// 1) Récupère l’objet JSON complet
const msg = items[0].json;

// 2) Métadonnées
const subject = msg.Subject     || 'Sans sujet';
const from    = msg.From        || msg.from?.text || 'Expéditeur inconnu';

// 3) Chercher le HTML ou le texte brut
let htmlBody = '';

// 3a) Cas où payload.parts existe
if (msg.payload?.parts) {
  function traverse(parts) {
    for (const p of parts) {
      if (p.mimeType === 'text/html' && p.body?.data) {
        htmlBody = Buffer.from(p.body.data, 'base64').toString('utf8');
        return;
      }
      if (p.parts) {
        traverse(p.parts);
        if (htmlBody) return;
      }
    }
  }
  traverse(msg.payload.parts);
}

// 3b) Sinon, cas où nœud Gmail a directement renvoyé textAsHtml
if (!htmlBody && msg.textAsHtml) {
  htmlBody = msg.textAsHtml;
}

// 3c) Sinon, on tombe sur text brut
if (!htmlBody && msg.text) {
  htmlBody = msg.text.replace(/\r?\n/g, '<br>');
}

// 3d) Fallback
if (!htmlBody) {
  htmlBody = '(corps vide)';
}

// 4) Construire le HTML de sortie - MODIFIÉ ICI (TOUT SUR UNE LIGNE)
const outHtml = `<style>h3.mail-subject,p.mail-sender{margin-block-start:0.2em;margin-block-end:0.2em;}hr.mail-divider{margin-top:0.3em;margin-bottom:0.5em;}</style><h3 class="mail-subject">${subject}</h3><p class="mail-sender"><b>De :</b> ${from}</p><hr class="mail-divider">${htmlBody}`.trim();

// 5) Retourne l’HTML prêt à afficher dans l’app
return [
  {
    json: {
      html: outHtml
    }
  }
];

return [{
  json: {
    // Corps du mail tel que renvoyé par l’IA
    mailBody:   $json.output || $json.message,
    // Alias `message` pour rester compatible avec ton app Flutter
    message:    $json.output || $json.message,
    // Provenant directement du Webhook (body)
    recipientEmail:  $items("Main_agent AI")[0].json.body.recipientEmail,
    originalSubject: $items("Main_agent AI")[0].json.body.originalSubject,
    originalMailId:  $items("Main_agent AI")[0].json.body.originalMailId,
  }
}];

const raw = items[0].json.output;

/* ─── 1. tableau déjà parsé ───────────────────────────── */
if (Array.isArray(raw)) {
  return raw.map(r => ({ json: r }));          // [{json},{json}…]
}

/* ─── 2. chaîne (peut être entourée de ```json … ```) ─── */
if (typeof raw === 'string') {
  // enlève les balises Markdown éventuelles
  const cleaned = raw.replace(/```json|```/g, '').trim();

  // chaîne = tableau JSON → on le renvoie item par item
  if (cleaned.startsWith('[')) {
    try {
      const arr = JSON.parse(cleaned);
      if (Array.isArray(arr)) {
        return arr.map(r => ({ json: r }));
      }
    } catch (_) { /* ignore, tombera au cas 3 */ }
  }

  // ─── 3. simple phrase (confirmation suppression) ───
  return [{ json: { message: cleaned } }];
}

/* ─── 4. format inattendu ─── */
return [{ json: { message: 'Format non reconnu' } }];

// Code structurer pour edit-reply
return [{
  json: {
    // Le texte corrigé renvoyé par l’IA
    mailBody:       $json.output || $json.message,
    // On re-propage les mêmes métadonnées que dans le Set
    recipientEmail: $items('Set Edit Reply Prompt')[0].json.recipientEmail,
    originalSubject:$items('Set Edit Reply Prompt')[0].json.originalSubject,
    originalMailId: $items('Set Edit Reply Prompt')[0].json.originalMailId,
  }
}];

